import assert from 'node:assert/strict'
import { test } from 'node:test'
import { slugify } from '../src/slugify.js'

test('lowercases and joins words with hyphens', () => {
  assert.equal(slugify('Hello World'), 'hello-world')
})

input.old_string:
test('lowercases and joins words with hyphens', () => {
  assert.equal(slugify('Hello World'), 'hello-world')
})

input.new_string:
test('lowercases and joins words with hyphens', () => {
  assert.equal(slugify('Hello World'), 'hello-world')
})

test('turns accented letters into plain ASCII letters', () => {
  assert.equal(slugify('Crème Brûlée'), 'creme-brulee')
  assert.equal(slugify('Déjà Vu, Ñandú & Çà'), 'deja-vu-nandu-ca')
})

test('collapses any run of non-alphanumeric characters into one hyphen', () => {
  assert.equal(slugify('Crème Brûlée -- 2 Ways!'), 'creme-brulee-2-ways')
  assert.equal(slugify('a/b\\c.d__e'), 'a-b-c-d-e')
})

test('has no leading or trailing hyphens', () => {
  assert.equal(slugify('  --Hello World--  '), 'hello-world')
  assert.equal(slugify('!!!'), '')
})

